function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 30) return 'grid needs 1 to 30 rows.';
  const cols = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (cols < 1 || cols > 30) return 'Each row needs 1 to 30 cells.';
  let ones = 0;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    for (const value of row) {
      if (value !== 0 && value !== 1) return 'Each cell is 0 or 1.';
      ones += value;
    }
  }
  if (ones < 3) return 'grid needs at least three 1s.';
  return null;
}

