function minimumSum(grid) {
  const rows = grid.length;
  const cols = grid[0].length;

  // Area of the smallest rectangle around the 1s in rows top..bottom, columns left..right (0 when there are none).
  const cover = (top, bottom, left, right) => {
    let minRow = rows, maxRow = -1, minCol = cols, maxCol = -1;
    for (let r = top; r <= bottom; r++) {
      for (let c = left; c <= right; c++) {
        if (grid[r][c] === 1) {
          minRow = Math.min(minRow, r);
          maxRow = Math.max(maxRow, r);
          minCol = Math.min(minCol, c);
          maxCol = Math.max(maxCol, c);
        }
      }
    }
    return maxRow < 0 ? 0 : (maxRow - minRow + 1) * (maxCol - minCol + 1);
  };

  const lastRow = rows - 1;
  const lastCol = cols - 1;
  // The two halves on each side of a cut below row i, and of a cut right of column j.
  const topHalf = [], bottomHalf = [], leftHalf = [], rightHalf = [];
  for (let i = 0; i < lastRow; i++) {
    topHalf.push(cover(0, i, 0, lastCol));
    bottomHalf.push(cover(i + 1, lastRow, 0, lastCol));
  }
  for (let j = 0; j < lastCol; j++) {
    leftHalf.push(cover(0, lastRow, 0, j));
    rightHalf.push(cover(0, lastRow, j + 1, lastCol));
  }

  let best = Infinity;
  // Cuts below rows i and j: three bands stacked on top of each other.
  for (let i = 0; i < lastRow; i++) {
    for (let j = i + 1; j < lastRow; j++) {
      best = Math.min(best, topHalf[i] + cover(i + 1, j, 0, lastCol) + bottomHalf[j]);
    }
  }
  // Cuts right of columns i and j: three bands side by side.
  for (let i = 0; i < lastCol; i++) {
    for (let j = i + 1; j < lastCol; j++) {
      best = Math.min(best, leftHalf[i] + cover(0, lastRow, i + 1, j) + rightHalf[j]);
    }
  }
  // One cut of each kind: one half stays whole and the opposite half splits into two corners.
  for (let i = 0; i < lastRow; i++) {
    for (let j = 0; j < lastCol; j++) {
      const topLeft = cover(0, i, 0, j);
      const topRight = cover(0, i, j + 1, lastCol);
      const bottomLeft = cover(i + 1, lastRow, 0, j);
      const bottomRight = cover(i + 1, lastRow, j + 1, lastCol);
      best = Math.min(best, topHalf[i] + bottomLeft + bottomRight, bottomHalf[i] + topLeft + topRight);
      best = Math.min(best, leftHalf[j] + topRight + bottomRight, rightHalf[j] + topLeft + bottomLeft);
    }
  }
  return best;
}

