function minimumSum(grid) {
  // Put every 1 into one of three groups; the groups' bounding boxes must be non-empty and pairwise disjoint.
  const ones = [];
  grid.forEach((row, r) => row.forEach((value, c) => { if (value === 1) ones.push([r, c]); }));
  const boxes = [null, null, null];
  const overlap = (a, b) => a[0] <= b[1] && b[0] <= a[1] && a[2] <= b[3] && b[2] <= a[3];
  let best = Infinity;
  const place = k => {
    if (k === ones.length) {
      if (boxes.some(box => box === null)) return;
      if (overlap(boxes[0], boxes[1]) || overlap(boxes[0], boxes[2]) || overlap(boxes[1], boxes[2])) return;
      best = Math.min(best, boxes.reduce((sum, b) => sum + (b[1] - b[0] + 1) * (b[3] - b[2] + 1), 0));
      return;
    }
    const [r, c] = ones[k];
    for (let g = 0; g < 3; g++) {
      const saved = boxes[g];
      boxes[g] = saved === null ? [r, r, c, c] : [Math.min(saved[0], r), Math.max(saved[1], r), Math.min(saved[2], c), Math.max(saved[3], c)];
      place(k + 1);
      boxes[g] = saved;
    }
  };
  place(0);
  return best;
}

