function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  for (;;) {
    const rows = large ? int(24, 30) : int(1, 5);
    const cols = large ? int(24, 30) : int(1, 5);
    const grid = Array.from({ length: rows }, () => new Array(cols).fill(0));
    const style = rand();
    if (style < 0.5) {
      // A few loose clusters of 1s.
      const clusters = int(2, 5);
      for (let k = 0; k < clusters; k++) {
        const top = int(0, rows - 1), left = int(0, cols - 1);
        const height = int(1, large ? 10 : 3), width = int(1, large ? 10 : 3);
        for (let r = top; r < Math.min(rows, top + height); r++)
          for (let c = left; c < Math.min(cols, left + width); c++)
            if (rand() < 0.7) grid[r][c] = 1;
      }
    } else {
      const density = large ? (style < 0.8 ? 0.003 + rand() * 0.03 : 0.3 + rand() * 0.7) : 0.15 + rand() * 0.6;
      for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
          if (rand() < density) grid[r][c] = 1;
    }
    const ones = grid.reduce((sum, row) => sum + row.reduce((a, b) => a + b, 0), 0);
    // Small grids keep at most 10 ones so the brute force (3^ones) stays quick.
    if (ones >= 3 && (large || ones <= 10)) return [grid];
  }
}
